arguments.new_str:
using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.Extensions.ML;

var builder = WebApplication.CreateBuilder(args);

// Train the model and save it
var modelPath = TrainModel(builder.Environment.ContentRootPath);

// Register pooled prediction engine (thread-safe for ASP.NET Core)
builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

app.MapGet("/", () => "Churn Predictor API — POST to /predict");

app.MapPost("/predict", (CustomerData input, PredictionEnginePool<CustomerData, ChurnPrediction> pool) =>
{
    var prediction = pool.Predict(input);
    return Results.Ok(new
    {
        WillChurn = prediction.PredictedLabel,
        Probability = prediction.Probability,
        Score = prediction.Score
    });
});

app.Run();

static string TrainModel(string contentRoot)
{
    var mlContext = new MLContext(seed: 42);
    var dataPath = Path.Combine(contentRoot, "Data", "customers.csv");
    var modelPath = Path.Combine(contentRoot, "Data", "ChurnModel.zip");

    // Load data
    var data = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');

    // Train/test split — never evaluate on training data
    var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

    // Build pipeline: encode Region as one-hot, concatenate features, train with FastTree
    var pipeline = mlContext.Transforms.Conversion
            .MapValueToKey("ChurnedKey", nameof(CustomerData.Churned))
        .Append(mlContext.Transforms.Categorical
            .OneHotEncoding("RegionEncoded", nameof(CustomerData.Region)))
        .Append(mlContext.Transforms.Concatenate("Features",
            nameof(CustomerData.Age),
            nameof(CustomerData.Income),
            "RegionEncoded",
            nameof(CustomerData.PurchaseHistory)))
        .Append(mlContext.BinaryClassification.Trainers.FastTree(
            labelColumnName: "ChurnedKey"))
        .Append(mlContext.Transforms.CopyColumns("PredictedLabel", "PredictedLabel"));

    // Train
    var model = pipeline.Fit(split.TrainSet);

    // Evaluate on test set
    var predictions = model.Transform(split.TestSet);
    var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "ChurnedKey");
    Console.WriteLine($"Model metrics — AUC: {metrics.AreaUnderRocCurve:F4}, " +
                      $"F1: {metrics.F1Score:F4}, Accuracy: {metrics.Accuracy:F4}");

    // Save model
    mlContext.Model.Save(model, data.Schema, modelPath);
    Console.WriteLine($"Model saved to {modelPath}");

    return modelPath;
}

public class CustomerData
{
    [LoadColumn(0)] public float Age { get; set; }
    [LoadColumn(1)] public float Income { get; set; }
    [LoadColumn(2)] public string Region { get; set; } = "";
    [LoadColumn(3)] public float PurchaseHistory { get; set; }
    [LoadColumn(4), ColumnName("Churned")] public string Churned { get; set; } = "";
}

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")]
    public bool PredictedLabel { get; set; }
    public float Probability { get; set; }
    public float Score { get; set; }
}

