31. static string TrainModel(string contentRoot)
32. {
33.     var mlContext = new MLContext(seed: 42);
34.     var dataPath = Path.Combine(contentRoot, "Data", "customers.csv");
35.     var modelPath = Path.Combine(contentRoot, "Data", "ChurnModel.zip");
36. 
37.     // Load data
38.     var data = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');
39. 
40.     // Train/test split — never evaluate on training data
41.     var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);
42. 
43.     // Build pipeline: map Yes/No to bool, encode Region, concatenate features, train
44.     var pipeline = mlContext.Transforms.CustomMapping<CustomerData, ChurnLabel>(
45.             (input, output) => output.Label = string.Equals(input.Churned, "Yes", StringComparison.OrdinalIgnoreCase),
46.             contractName: "ChurnMapping")
47.         .Append(mlContext.Transforms.Categorical
48.             .OneHotEncoding("RegionEncoded", nameof(CustomerData.Region)))
49.         .Append(mlContext.Transforms.Concatenate("Features",
50.             nameof(CustomerData.Age),
51.             nameof(CustomerData.Income),
52.             "RegionEncoded",
53.             nameof(CustomerData.PurchaseHistory)))
54.         .Append(mlContext.BinaryClassification.Trainers.FastTree(
55.             labelColumnName: "Label"));
56. 
57.     // Train
58.     var model = pipeline.Fit(split.TrainSet);
59. 
60.     // Evaluate on test set
61.     var predictions = model.Transform(split.TestSet);
