static string TrainModel(string contentRoot)
{
    var mlContext = new MLContext(seed: 42);
    var dataPath = Path.Combine(contentRoot, "Data", "customers.csv");
    var modelPath = Path.Combine(contentRoot, "Data", "ChurnModel.zip");

    // Load CSV and convert Yes/No label to bool
    var rows = File.ReadAllLines(dataPath)
        .Skip(1)
        .Where(line => !string.IsNullOrWhiteSpace(line))
        .Select(line =>
        {
            var parts = line.Split(',');
            return new CustomerTrainingData
            {
                Age = float.Parse(parts[0]),
                Income = float.Parse(parts[1]),
                Region = parts[2].Trim(),
                PurchaseHistory = float.Parse(parts[3]),
                Label = string.Equals(parts[4].Trim(), "Yes", StringComparison.OrdinalIgnoreCase)
            };
        })
        .ToList();

    var data = mlContext.Data.LoadFromEnumerable(rows);

    // Train/test split — never evaluate on training data
    var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

    // Build pipeline: encode Region as one-hot, concatenate features, train with FastTree
    var pipeline = mlContext.Transforms.Categorical
            .OneHotEncoding("RegionEncoded", nameof(CustomerData.Region))
        .Append(mlContext.Transforms.Concatenate("Features",
            nameof(CustomerData.Age),
            nameof(CustomerData.Income),
            "RegionEncoded",
            nameof(CustomerData.PurchaseHistory)))
        .Append(mlContext.BinaryClassification.Trainers.FastTree(
            labelColumnName: "Label"));

    // Train
    var model = pipeline.Fit(split.TrainSet);

    // Evaluate on test set
    var predictions = model.Transform(split.TestSet);
    try
    {
        var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
        Console.WriteLine($"Model metrics — AUC: {metrics.AreaUnderRocCurve:F4}, " +
                          $"F1: {metrics.F1Score:F4}, Accuracy: {metrics.Accuracy:F4}");
    }
    catch (ArgumentOutOfRangeException)
    {
        Console.WriteLine("Warning: Test set too small to compute metrics. Add more data for reliable evaluation.");
    }

    // Save model
    mlContext.Model.Save(model, data.Schema, modelPath);
    Console.WriteLine($"Model saved to {modelPath}");

    return modelPath;
}

